"""Loader for `harness.yaml` — round-trip YAML +
${ENV} interpolation + Pydantic validation."""

from __future__ import annotations

import os
import re
from pathlib import Path
from typing import Any

from pydantic import ValidationError
from ruamel.yaml import YAML

from harness.config.models import HarnessConfig

_ENV_PATTERN = re.compile(r"\$\{([A-Z_][A-Z0-9_]*)(?::-([^}]*))?\}")


class ConfigError(RuntimeError):
    """Raised when harness.yaml fails to parse or validate."""


def _interpolate_env(value: Any) -> Any:
    """Replace ${VAR} or ${VAR:-default} in strings. Recurses into dicts and lists.

    Missing variables without a default raise ConfigError so problems surface at load time.
    """
    if isinstance(value, str):
        def repl(m: re.Match[str]) -> str:
            var, default = m.group(1), m.group(2)
            env = os.environ.get(var)
            if env is not None:
                return env
            if default is not None:
                return default
            raise ConfigError(f"environment variable ${{{var}}} is not set and has no default")

        return _ENV_PATTERN.sub(repl, value)
    if isinstance(value, list):
        return [_interpolate_env(item) for item in value]
    if isinstance(value, dict):
        return {k: _interpolate_env(v) for k, v in value.items()}
    return value


def load_config(path: Path) -> HarnessConfig:
    """Load and validate harness.yaml at `path`."""
    if not path.exists():
        raise ConfigError(f"config file not found: {path}")

    yaml = YAML(typ="safe")
    try:
        raw = yaml.load(path.read_text(encoding="utf-8"))
    except Exception as e:  # ruamel raises a hierarchy; flatten to ConfigError
        raise ConfigError(f"yaml parse error in {path}: {e}") from e

    if not isinstance(raw, dict):
        raise ConfigError(f"{path} must be a YAML mapping at the top level")

    interpolated = _interpolate_env(raw)

    try:
        return HarnessConfig.model_validate(interpolated)
    except ValidationError as e:
        raise ConfigError(f"invalid config at {path}:\n{_format_validation_error(e)}") from e


def _format_validation_error(e: ValidationError) -> str:
    """Pydantic v2 default messages for regex constraints render the pattern
    through a stripper that can produce nonsense like '^*$'. Build a more
    human message field-by-field, with hints for common fields."""
    lines: list[str] = []
    for err in e.errors():
        loc = ".".join(str(p) for p in err.get("loc", []))
        msg = err.get("msg", "")
        ctx = err.get("ctx") or {}
        input_val = err.get("input")

        # Special-cased fields with friendlier hints.
        if loc == "project.name" and err.get("type", "").startswith("string_pattern"):
            hint = (
                f"Project name must be lowercase letters, digits, hyphens; "
                f"start with a letter. Got: {input_val!r}. "
                f"Try: harness init --force  (wizard auto-slugifies)."
            )
            lines.append(f"  {loc}: {hint}")
            continue
        if err.get("type", "").startswith("string_pattern"):
            pat = ctx.get("pattern", "<unknown>")
            lines.append(
                f"  {loc}: value {input_val!r} does not match required pattern {pat!r}"
            )
            continue
        lines.append(f"  {loc}: {msg}  (got {input_val!r})")
    return "\n".join(lines) if lines else str(e)


def dump_config(config: HarnessConfig, path: Path) -> None:
    """Write a HarnessConfig back to YAML, preserving key order from the model."""
    yaml = YAML()
    yaml.default_flow_style = False
    yaml.indent(mapping=2, sequence=4, offset=2)
    with path.open("w", encoding="utf-8") as f:
        yaml.dump(config.model_dump(mode="json", exclude_none=True), f)
